begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1718 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:6f6157682bba7d1b46c44ff2' and md5(to_jsonb(t)::text)='227457c24ccde2911cd8a36a5dc96681')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:6f6157682bba7d1b46c44ff2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bb04627f9ddf28b5$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este libro contiene ejercicios de intuición y perspicacia, y sus palabras están impregnadas de magia. Si dedicas 48 horas durante un periodo de 6 días, como mucho, a estudiar el contenido del libro y poner en práctica sus indicaciones, tu puntuación de Sabiduría aumentará en 2, así como tu máximo para esa puntuación. Después, el manual perderá su magia, pero la recuperará cuando pase un siglo.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_bb04627f9ddf28b5$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:6f6157682bba7d1b46c44ff2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:711f85d63c831b6b0310fb58' and md5(to_jsonb(t)::text)='0a33293b24aa4a48b8e683e1a4a3b653')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:711f85d63c831b6b0310fb58';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5efa713461f5b120$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Mientras lleves la espada contigo, también obtendrás un bonificador de +1 a las tiradas de salvación.\n\nDeseo. La espada tiene 1d4 – 1 cargas. Mientras la empuñes, podrás usar una acción para gastar 1 carga y lanzar el conjuro deseo desde ella. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer. La espada pierde esta propiedad si no le quedan cargas.\n\nFortuna. Si llevas la espada contigo, puedes recurrir a su fortuna (no requiere acción) para repetir una tirada de ataque, una prueba de característica o una tirada de salvación desfavorable. Deberás usar el nuevo resultado. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5efa713461f5b120$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:711f85d63c831b6b0310fb58';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:72d78d4649313d1a3f8b5b1e' and md5(to_jsonb(t)::text)='e92f5abd13f7dbf15bec0b538f7a0a10')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:72d78d4649313d1a3f8b5b1e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:72d78d4649313d1a3f8b5b1e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:741c6683c6d99e0c4fd359ba' and md5(to_jsonb(t)::text)='2539737ef94cab9b054f868029d5c01c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:741c6683c6d99e0c4fd359ba';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_383ecff6579ff2c0$"Objeto · Precio base · Peso\nAbrojos (bolsa de 20) · 1 po · 2 lb\n\nAbrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_383ecff6579ff2c0$::jsonb,true),'{features}',$text_816adba2fd0e635e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_816adba2fd0e635e$::jsonb,true),'{rules,definition,description}',$text_ad9e1c5eb1c88758$[{"id":"official-table","rows":[["Abrojos (bolsa de 20)","1 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_ad9e1c5eb1c88758$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:741c6683c6d99e0c4fd359ba';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:74a52ed7f52b736c3d425209' and md5(to_jsonb(t)::text)='bdf662bcd9d789b20b19ed8bc785ef1d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:74a52ed7f52b736c3d425209';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_75d1cfa2fedc4884$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cubo mide 7,5 cm de lado e irradia una energía mágica palpable. Cada una de las seis caras del cubo está conectada con un plano de existencia diferente, entre ellos el Plano Material. El resto de planos los determina tu GM.\n\nPuedes utilizar una acción para pulsar un lado del cubo y lanzar el conjuro portal, de forma que se abra un portal hacia el plano conectado con esa cara. De forma alternativa, si utilizas una acción para pulsar una cara dos veces, puedes lanzar el conjuro desplazamiento entre planos (CD de salvación 17) con el cubo y transportar a los objetivos al plano conectado con esa cara.\n\nEl cubo tiene 3 cargas. Cada uso gasta 1 carga. El cubo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_75d1cfa2fedc4884$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:74a52ed7f52b736c3d425209';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:74d803c9be726373ff91c34e' and md5(to_jsonb(t)::text)='447413e3a67c11874f948dec0d375cb0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:74d803c9be726373ff91c34e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_84e82a45a64001fe$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. También tiene las propiedades adicionales que se mencionan a continuación. Cuando se utilice una de ellas, no podrá volver a usarse hasta el siguiente amanecer.\n\nGolpe relampagueante. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el objetivo sufra 2d6 de daño de relámpago adicional.\n\nGolpe atronador. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás hacer que el bastón emita un chasquido atronador que se oiga a 90 m de distancia. El objetivo impactado deberá superar una tirada de salvación de Constitución con CD 17 o quedará aturdido hasta el final de tu siguiente turno.\n\nRelámpago. Puedes utilizar una acción para que un relámpago surja de la punta del bastón en una línea de 1,5 m de ancho y 36 m de largo. Todas las criaturas situadas en la línea deberán hacer una tirada de salvación de Destreza con CD 17; sufrirán 9d6 de daño de relámpago si la fallan o la mitad del daño si la superan.\n\nTrueno. Puedes utilizar una acción para hacer que el bastón emita un trueno ensordecedor que se oiga a 180 m de distancia. Todas las criaturas situadas a 18 m o menos de ti (menos tú) deberán realizar una tirada de salvación de Constitución con CD 17. Si la fallan, sufrirán 2d6 de daño de trueno y quedarán ensordecidas durante 1 minuto. Si la superan, sufrirán la mitad del daño y no quedarán ensordecidas.\n\nTruenos y relámpagos. Puedes utilizar una acción para usar las propiedades “relámpago” y “trueno” a la vez. Hacer esto no consume el uso diario de esas propiedades, solo de esta.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_84e82a45a64001fe$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:74d803c9be726373ff91c34e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:769ff7952f0ed75b062d6044' and md5(to_jsonb(t)::text)='22ec79bbe9e33dc40bad709418800fff')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:769ff7952f0ed75b062d6044';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bff3bb03f6016afe$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto de “agrandar” del conjuro agrandar/reducir durante 1d4 horas (no requiere concentración). El color rojo del líquido de la poción se expande continuamente a partir de una gota diminuta para teñir el líquido transparente que la rodea. A continuación, se vuelve a contraer. Si agitas la botella, no se interrumpirá el proceso.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bff3bb03f6016afe$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:769ff7952f0ed75b062d6044';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:77c1a86f7bceca1fb79453c1' and md5(to_jsonb(t)::text)='dadb084553a2c6c30284b55378456dd0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:77c1a86f7bceca1fb79453c1';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_80073a099c59bdfb$[{"id":"official-base-table","rows":[["Lanza","1 po","3 lb","1d6 perforante","+0","Arrojadiza, Versátil","20/60","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_80073a099c59bdfb$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_0170730ceade80f6$["official-base-table","property-thrown","property-versatile","family-rule"]$text_0170730ceade80f6$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:77c1a86f7bceca1fb79453c1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:784bd660a08f0f45bc4bd35e' and md5(to_jsonb(t)::text)='d4a77b2ce07cbe084e10409d95220ffe')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:784bd660a08f0f45bc4bd35e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f8d4aa1b82e82ffc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro proyectil mágico desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 1 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f8d4aa1b82e82ffc$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:784bd660a08f0f45bc4bd35e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:787b7ce6af1d2525c342d664' and md5(to_jsonb(t)::text)='47c3b7c3ed045e91e165db5e631ffdf9')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:787b7ce6af1d2525c342d664';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_53c7703c439bc2cd$[{"id":"mundane-assisted-use","kind":"other","name":"Proyectiles de la bolsa","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"La bolsa contiene 20 balas de honda. El precio y peso corresponden a la bolsa completa.\n\nDuración: Según su uso..","showInActions":false}]$text_53c7703c439bc2cd$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:787b7ce6af1d2525c342d664';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:78a330dcbaa0773138491e90' and md5(to_jsonb(t)::text)='e2bf00c13c265ddafccf795be13ceece')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:78a330dcbaa0773138491e90';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:78a330dcbaa0773138491e90';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:79852c0176e7952ae8226dcc' and md5(to_jsonb(t)::text)='20007500274ba715d29c1f7e9a8f6b1f')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:79852c0176e7952ae8226dcc';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4a48d0c039253fa2$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes usar una acción adicional para lanzar esta espada mágica al aire y pronunciar la palabra de activación. Cuando lo hagas, el arma comenzará a levitar, volará hasta 9 m y atacará a una criatura de tu elección que esté a 1,5 m o menos de ella. La espada utiliza tu tirada de ataque y tu modificador por característica para las tiradas de daño.\n\nMientras la espada esté levitando, podrás emplear una acción adicional para que vuele hasta 9 m hacia otro lugar situado a 9 m o menos de ti. Como parte de la misma acción adicional, podrás hacer que la espada ataque a una criatura situada a 1,5 m o menos de ella.\n\nDespués de que la espada flotante ataque por cuarta vez, volará hasta 9 m y tratará de regresar a tu mano. Si no tienes ninguna mano libre, caerá a tus pies. Si la espada tiene vía libre hasta ti, se te acercará todo lo que pueda y después caerá al suelo. También dejará de levitar si la agarras o si te alejas más de 9 m de ella.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4a48d0c039253fa2$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:79852c0176e7952ae8226dcc';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:79a0a5ea6cf16922cb5a78f7' and md5(to_jsonb(t)::text)='5024bc74a262455aed9bee7d918bfae0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:79a0a5ea6cf16922cb5a78f7';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_57266ba65d589236$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nCuando impactes a un gigante con ella, el gigante sufrirá 2d6 de daño adicional del tipo del arma y deberá superar una tirada de salvación de Fuerza con CD 15 o caerá derribado. En lo que concierne a esta arma, “gigante” se refiere a cualquier criatura con el tipo “gigante”, incluidos seres como ettins y trolls.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_57266ba65d589236$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:79a0a5ea6cf16922cb5a78f7';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:79ac3b7e18f9352b31f1cde4' and md5(to_jsonb(t)::text)='77bacecbd0fd92e077d0e34ef167f0bc')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:79ac3b7e18f9352b31f1cde4';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f22a284ca7ab083d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas botas forradas de pelaje son ceñidas y calentitas. Mientras las lleves puestas, obtendrás los siguientes beneficios: • Tienes resistencia al daño de frío. • El terreno difícil creado por hielo o nieve no te afecta. • Puedes aguantar temperaturas de hasta –45 °C sin más protección. Si llevas ropas pesadas, puedes soportar hasta –75 °C.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f22a284ca7ab083d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:79ac3b7e18f9352b31f1cde4';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7a41873e8602ad756e91bf15' and md5(to_jsonb(t)::text)='1c533a002885abdb3759ff56ce0583d3')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7a41873e8602ad756e91bf15';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_5d969e1c90876246$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, podrás usar una acción para nombrar un lugar que conozcas de otro plano de existencia. Después, haz una prueba de Inteligencia con CD 15. Si la superas, lanzarás el conjuro desplazamiento entre planos. Si la fallas, tú y cualquier criatura y objeto que esté a 4,5 m o menos de ti os desplazaréis a un destino aleatorio. Tira 1d100. Si sacas entre 1 y 60, viajáis a un lugar aleatorio en el plano de existencia nombrado. Si sacas entre 61 y 100, aparecéis en un plano determinado al azar.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5d969e1c90876246$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7a41873e8602ad756e91bf15';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7c1a658894dfd5edf11c9260' and md5(to_jsonb(t)::text)='570822c8df7679a3ef84c98ce3620ae1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7c1a658894dfd5edf11c9260';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_8b05c428c79f2f94$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta sustancia viscosa y blanca como la leche puede crear un vínculo adhesivo permanente entre dos objetos cualesquiera. Debe almacenarse en un bote o frasco que se haya untado con aceite escurridizo. En el momento de encontrar el recipiente, contendrá 30 g + 1d6 × 30 g.\n\n30 g de pegamento pueden cubrir una superficie cuadrada de 30 cm de lado. El pegamento tarda 1 minuto en asentarse. En cuanto lo haga, el vínculo que crea solo se puede romper si se aplica un disolvente universal o un aceite de etereidad o con un conjuro deseo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8b05c428c79f2f94$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7c1a658894dfd5edf11c9260';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7c5164541d5c7d2d1179ff8e' and md5(to_jsonb(t)::text)='03d1866787cbe906adb505871cac7b76')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7c5164541d5c7d2d1179ff8e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_447d1b12fca0c2f9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta vara de hierro posee un botón en uno de sus extremos. Puedes usar una acción para pulsar el botón y hacer que la vara se fije mágicamente en el sitio. Hasta que otra criatura o tú utilicéis una acción para pulsar de nuevo el botón, la vara no se moverá, desafiando a la gravedad si es necesario. Puede aguantar hasta 4000 kg de peso; una cantidad mayor provocará que se desactive y caiga. Una criatura puede usar su acción para realizar una prueba de Fuerza con CD 30. Si tiene éxito, moverá la vara hasta 3 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_447d1b12fca0c2f9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7c5164541d5c7d2d1179ff8e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c' and md5(to_jsonb(t)::text)='08c9c1debe8abd2445b68eaaa80af94f')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7d150b153865ce199ca4823c';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_13c2783a0f6c5ecf$"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_13c2783a0f6c5ecf$::jsonb,true),'{features}',$text_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_20d6da3fc6e17a06$::jsonb,true),'{rules,definition,description}',$text_a2a80e2fdb6b3797$[{"id":"official-table","rows":[["Amuleto","5 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a2a80e2fdb6b3797$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:7d150b153865ce199ca4823c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7d468487c373342123ec2cc0' and md5(to_jsonb(t)::text)='a5ed977c31eb48153910207a32257dca')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7d468487c373342123ec2cc0';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f754dbe1c023aca9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Las piedras Ioun se llaman así por Ioun, un dios del conocimiento y la profecía adorado en algunos mundos. Existen muchos tipos de piedras Ioun, cada uno de ellos con una combinación distinta de forma y color.\n\nCuando utilices una acción para lanzar una de estas piedras al aire, la piedra girará alrededor de tu cabeza a una distancia de 1d3 × 30 cm y te otorgará un beneficio. A partir de entonces, otra criatura deberá utilizar una acción para agarrar o atrapar la piedra y separarla de ti, ya sea superando una tirada de ataque contra una CA de 24 o una prueba de Destreza (Acrobacias) con CD 24. Puedes utilizar una acción para tomar y guardar la piedra, lo que pone fin a su efecto.\n\nUna piedra tiene una CA de 24, 10 puntos de golpe y resistencia a todo el daño. Se considera un objeto vestido mientras gira alrededor de tu cabeza.\n\nMaestría (legendaria). Mientras este prisma verde pálido gire alrededor de tu cabeza, tu bonificador por competencia aumenta en 1.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f754dbe1c023aca9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7d468487c373342123ec2cc0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1' and md5(to_jsonb(t)::text)='331f24332a89cf552eeb28d9202d3946')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7e70af915a0f0151f102d0a1';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_569cb37696c7d3eb$"Objeto · Precio base · Peso\nHerramientas de cartógrafo · 15 po · 6 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_569cb37696c7d3eb$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_08ae83fa509ef72d$[{"id":"official-table","rows":[["Herramientas de cartógrafo","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_08ae83fa509ef72d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:7e70af915a0f0151f102d0a1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec' and md5(to_jsonb(t)::text)='ed14bfe49fb972d2cefc4cdadc60b1ea')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7ed1857c411cd63b4a9ae3ec';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_3bd2fbd4a29a4876$[{"id":"official-base-table","rows":[["Ballesta ligera","25 po","5 lb","1d8 perforante","+0","Munición, Recarga, A dos manos","80/320"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_3bd2fbd4a29a4876$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_62229fa2c2080f2d$["official-base-table","property-ammunition","property-loading","property-two-handed","family-rule"]$text_62229fa2c2080f2d$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:7ed1857c411cd63b4a9ae3ec';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7f88e7a006665acd21818ae9' and md5(to_jsonb(t)::text)='90daa81a2434d794d658b3e0407ea138')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7f88e7a006665acd21818ae9';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_94f1895779fee577$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de explorador de mazmorras (12 po). Incluye una mochila, una palanqueta, un martillo, 10 pitones, 10 antorchas, un yesquero, raciones para 10 días y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$text_94f1895779fee577$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7f88e7a006665acd21818ae9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:7fee756c80e074dd2dc47947' and md5(to_jsonb(t)::text)='d75450080d92de9f140537adad052886')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:7fee756c80e074dd2dc47947';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_bb33c31630364152$[{"id":"legacy-bonus-0","kind":"passive","name":"PassivePerception","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +5 a la Percepción Pasiva mientras se usa y está sintonizado.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas lentes de cristal cubren los ojos. Mientras las lleves puestas, tendrás ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista. En condiciones de buena visibilidad, podrás ver detalles de criaturas y objetos muy lejanos de incluso 60 cm de diámetro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bb33c31630364152$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:7fee756c80e074dd2dc47947';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:81d0edc3f74b29c0545f788e' and md5(to_jsonb(t)::text)='ef8e481ef1ffc6fa27a6658a25e33f4a')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:81d0edc3f74b29c0545f788e';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:81d0edc3f74b29c0545f788e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:821a97f9c8fb63e7bd326b70' and md5(to_jsonb(t)::text)='ad958ebcb15b6e7fc18cd96dc02cd51c')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:821a97f9c8fb63e7bd326b70';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_f0e511db536bffb9$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Los puntos de golpe perdidos por el daño de esta arma solo pueden recuperarse mediante un descanso corto o largo, no mediante la regeneración, la magia o cualquier otro medio.\n\nUna vez por turno, cuando impactes a una criatura con un ataque usando esta arma mágica, podrás herirla. Al principio de cada turno de la criatura herida, sufrirá 1d4 de daño necrótico por cada vez que la hayas herido y luego podrá realizar una tirada de salvación de Constitución con CD 15 para acabar con el efecto de esas heridas si la supera. Como alternativa, la criatura herida u otra que se encuentre a 1,5 m o menos de ella podrá usar una acción para realizar una prueba de Sabiduría (Medicina) con CD 15 y acabar con el efecto de las heridas si la supera.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f0e511db536bffb9$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:821a97f9c8fb63e7bd326b70';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:82bec804f111fbf655ff7dcf' and md5(to_jsonb(t)::text)='2bfe18de815d4b130551ef272b8832d1')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:82bec804f111fbf655ff7dcf';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4ca76cc6ddf1af62$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes resistencia a un tipo de daño mientras lleves esta armadura. Tu GM elige el tipo o lo determina al azar de entre las opciones que hay a continuación.\n\n1 · Ácido · 6 · Psíquico\n2 · Frío · 7 · Radiante\n3 · Fuego · 8 · Relámpago\n4 · Fuerza · 9 · Trueno\n5 · Necrótico · 10 · Veneno\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4ca76cc6ddf1af62$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:82bec804f111fbf655ff7dcf';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:837132a2b546795dcbf8cd3c' and md5(to_jsonb(t)::text)='d7e0fbabbd0e9b3108ff3734aa67ed7b')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:837132a2b546795dcbf8cd3c';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_7193c7266114fc5c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta diadema, podrás utilizar una acción para lanzar el conjuro rayo abrasador. Cuando lleves a cabo los ataques del conjuro, tu bonificador de ataque será de +5. La diadema no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7193c7266114fc5c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:837132a2b546795dcbf8cd3c';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8442091e560c1191cf13f5d2' and md5(to_jsonb(t)::text)='86a5736b7cffa030cde54dc50ba4decd')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8442091e560c1191cf13f5d2';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_d21d948ae4ba094c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este diminuto objeto parece una pluma. Existen diferentes tipos de fichas de pluma, cada uno con un efecto diferente de un solo uso. Tu GM elige el tipo de ficha o lo determina al azar.\n\n01–15 · Abanico 61–75 ·  · Bote cisne\n16–35 · Ancla 76–85 ·  · Látigo\n36–60 · Árbol 86–00 ·  · Pájaro\n\nAbanico. Si te encuentras en un bote o barco, puedes emplear una acción para tirar la ficha al aire hasta 3 m de altura. La ficha desaparecerá y un abanico gigante en movimiento ocupará su lugar. El abanico flota y crea un viento lo bastante fuerte como para henchir las velas de un barco y aumentar su velocidad en 7,5 km/h durante 8 horas. Como acción, puedes hacer que el abanico desaparezca.\n\nAncla. Puedes emplear una acción para tocar un bote o barco con la ficha. Durante las próximas 24 horas, la embarcación no podrá moverse de ninguna manera. Volver a tocarla con la ficha pone fin al efecto. Cuando acabe el efecto, la ficha desaparece.\n\nÁrbol. Debes estar al aire libre para poder usar esta ficha. Puedes emplear una acción para tocar con la ficha un espacio sin ocupar del suelo. La ficha desaparecerá y un roble no mágico ocupará su lugar. El árbol mide 18 m de alto, el diámetro de su tronco es de 1,5 m y las ramas de su copa cubren un radio de 6 m.\n\nBote cisne. Puedes emplear una acción para tocar con la ficha una masa de agua de al menos 18 m de diámetro. La ficha desaparecerá y un bote de 15 m de largo y 6 m de ancho con la forma de un cisne ocupará su lugar. El bote se autopropulsa y se desplaza por el agua a una velocidad de 9 km/h. Puedes emplear una acción mientras te encuentres en el barco para ordenarle moverse o girar hasta 90 grados. La embarcación puede transportar hasta treinta y dos criaturas Medianas o de menor tamaño. Una criatura Grande cuenta como cuatro criaturas Medianas, mientras que una criatura Enorme cuenta como nueve. El bote permanece durante 24 horas y después desaparece. Como acción, puedes hacer que el bote desaparezca.\n\nLátigo. Puedes emplear una acción para tirar la ficha a 3 m o menos de ti. La ficha desaparecerá y un látigo flotante ocupará su lugar. A continuación, podrás utilizar una acción adicional para realizar un ataque de conjuro cuerpo a cuerpo contra una criatura que esté a 3 m o menos del látigo, con un bonificador de ataque de +9. Si impacta, el objetivo recibe 1d6 + 5 de daño de fuerza.\n\nComo acción adicional durante tu turno, puedes mover el látigo hasta 6 m y repetir el ataque contra una criatura que se encuentre a 3 m o menos de ella. El látigo desaparecerá después de 1 hora, si usas una acción para hacerlo desaparecer o si estás incapaci- tado o mueres.\n\nPájaro. Puedes emplear una acción para tirar la ficha al aire a 1,5 m de altura. La ficha desaparecerá y un enorme pájaro multicolor ocupará su lugar. El pájaro tiene el perfil de un roc, pero obedece las órdenes sencillas que le des y no puede atacar. Puede transportar hasta 250 kg mientras vuela a su velocidad máxima (24 km/h y, como máximo, 216 km al día, con descansos de una hora cada 3 horas de vuelo) o 500 kg a la mitad de esa velocidad. El ave desaparece tras volar su distancia máxima durante un día o si sus puntos de golpe se reducen a 0. Como acción, puedes hacer que el pájaro desaparezca.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d21d948ae4ba094c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8442091e560c1191cf13f5d2';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:844e28dd6ac8a83fb3ca8ef0' and md5(to_jsonb(t)::text)='e16c0a58f4c2aa5b568e80b3b0f5d529')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:844e28dd6ac8a83fb3ca8ef0';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_ca5e6004250fdca5$"Objeto · Precio base · Peso\nLibro de conjuros · 50 po · 3 lb\n\nLibro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_ca5e6004250fdca5$::jsonb,true),'{features}',$text_aa29c45791edda23$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_aa29c45791edda23$::jsonb,true),'{rules,definition,description}',$text_d0cdc14ec2a16eb6$[{"id":"official-table","rows":[["Libro de conjuros","50 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Libro de conjuros. Indispensable para los magos, un libro de conjuros es un tomo encuadernado en cuero con 100 páginas de vitela en blanco, adecuadas para escribir conjuros.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_d0cdc14ec2a16eb6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:844e28dd6ac8a83fb3ca8ef0';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:85b343f16d824ce798cbb857' and md5(to_jsonb(t)::text)='ea37448bdfca5c8d4b44bc2cf9477c03')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:85b343f16d824ce798cbb857';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_70b341cbb9386adf$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Una flecha asesina es un arma mágica diseñada para matar a un tipo concreto de criatura. Algunas son más específicas que otras. Por ejemplo, hay tanto flechas asesinas de dragones como flechas asesinas de dragones azules. Si una criatura que pertenezca al tipo, raza o grupo asociado con una flecha asesina recibe daño de ella, deberá realizar una tirada de salvación de Constitución con CD 17; sufrirá 6d10 de daño perforante adicional si la falla o la mitad del daño adicional si la supera.\n\nEn cuanto una flecha asesina inflige su daño adicional a una criatura, se vuelve una flecha no mágica.\n\nExisten otros tipos de municiones similares, como los virotes asesinos para ballestas, aunque las flechas son las más comunes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_70b341cbb9386adf$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:85b343f16d824ce798cbb857';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:86cffac954a9cc099e37eccf' and md5(to_jsonb(t)::text)='12b7ef11cc34cba5ecdc8342ab9a9156')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:86cffac954a9cc099e37eccf';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_00e28e9a737512ca$"Objeto · Precio base · Peso\nAlforjas · 4 po · 8 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_00e28e9a737512ca$::jsonb,true),'{rules,definition,description}',$text_c6457c54b8f6c83d$[{"id":"official-table","rows":[["Alforjas","4 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_c6457c54b8f6c83d$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:86cffac954a9cc099e37eccf';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:886ad6ba49cfdb0b0988802e' and md5(to_jsonb(t)::text)='30c4c978cef20cb942d9f491710bd9bf')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:886ad6ba49cfdb0b0988802e';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_092dcf440fb6551f$"Objeto · Precio base · Peso\nLibro · 25 po · 5 lb\n\nLibro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_092dcf440fb6551f$::jsonb,true),'{features}',$text_a65602c74ff050f0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Libro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_a65602c74ff050f0$::jsonb,true),'{rules,definition,description}',$text_292b14a2b96e71ca$[{"id":"official-table","rows":[["Libro","25 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Libro. Un libro podría contener poemas, registros históricos, información perteneciente a un ámbito de conocimiento concreto, diagramas y notas sobre artilugios gnomos o prácticamente cualquier cosa que se pueda representar mediante texto o imágenes. Un libro que contenga conjuros recibe el nombre de “libro de conjuros” y se describe a continuación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_292b14a2b96e71ca$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:886ad6ba49cfdb0b0988802e';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:88c9115b7d543622bd1c0bde' and md5(to_jsonb(t)::text)='09a4cbc3f028140f3e13020f20ce81ab')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:88c9115b7d543622bd1c0bde';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_eb1c1509c017f08d$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"A primera vista, este objeto parece un barril de hierro sellado Grande que pesa 250 kg. El barril tiene un pestillo escondido, que se puede encontrar si se supera una prueba de Inteligencia (Investigación) con CD 20. Si se abre el pestillo, se accede a una escotilla en un extremo del barril, en el que pueden entrar dos criaturas Medianas o más pequeñas arrastrándose. Al fondo hay diez palancas dispuestas en fila en posición neutra que pueden levantarse o bajarse. Si se usan determinadas palancas, el aparato se transforma en una especie de langosta gigante.\n\nEl aparato del crustáceo es un objeto Grande con el siguiente perfil: Clase de Armadura: 20 Puntos de golpe: 200 Velocidad: 9 m, nadar 9 m (o 0 m en ambos casos si no se han extendido las patas y cola) Inmunidad a daño: psíquico, veneno El aparato puede utilizarse como vehículo, pero requiere un piloto para ello. Mientras la escotilla esté cerrada, el compartimento es estanco y hermético. Contiene aire suficiente para respirar durante 10 horas, divididas entre el número de criaturas que necesiten respirar en su interior.\n\nEl aparato flota en el agua. También puede sumergirse a una profundidad de 270 m. Por debajo de esta profundidad, el vehículo sufre 2d6 de daño contundente por minuto debido a la presión.\n\nUna criatura que esté en el compartimento puede utilizar una acción para subir o bajar hasta dos de las palancas del aparato. Después de cada uso, la palanca regresa a su posición neutra. Cada palanca, de izquierda a derecha, funciona como se muestra en la tabla “Palancas del aparato del crustáceo”. Palancas del aparato del crustáceo\n\n1 · La cola y las patas se extienden, lo que permite que el aparato camine y nade. · Las patas y la cola se retraen, lo que reduce la velocidad del aparato a 0 e impide que se beneficie de ningún bonificador a su velocidad.\n2 · La persiana de la ventana delantera se abre. · La persiana de la ventana delantera se cierra.\n3 · Las persianas de las ventanas laterales se abren (dos por lado). · Las persianas de las ventanas laterales se cierran (dos por lado).\n4 · Se extienden dos pinzas desde la parte delantera del aparato. · Las pinzas se retraen.\n5 · Cada pinza extendida lleva a cabo el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 1,5 m, un objetivo. Impacto: 7 (2d6) de daño contundente. · Cada pinza extendida lleva a cabo el siguiente ataque con arma cuerpo a cuerpo: +8 a impactar, alcance 1,5 m, un objetivo. Impacto: El objetivo quedará agarrado (CD 15 para escapar).\n6 · El aparato camina o nada hacia delante. · El aparato camina o nada hacia atrás.\n7 · El aparato gira 90 grados a la izquierda. · El aparato gira 90 grados a la derecha.\n8 · Unas linternas con forma de ojo emiten luz brillante en un radio de 9 m y luz tenue 9 m más allá. · La luz se apaga.\n9 · El aparato desciende hasta 6 m en un medio líquido. · El aparato asciende hasta 6 m en un medio líquido.\n10 · La escotilla trasera se abre. · La escotilla trasera se cierra.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_eb1c1509c017f08d$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:88c9115b7d543622bd1c0bde';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8a04f86771d4d29eeccaedd8' and md5(to_jsonb(t)::text)='2f8350e9f728508b53af665c2a33cd7e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8a04f86771d4d29eeccaedd8';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_72383d98f44f666c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El medallón tiene 3 cargas. Mientras lo lleves puesto, podrás utilizar una acción y gastar 1 carga para lanzar el conjuro detectar pensamientos (CD de salvación 13) desde él. El medallón recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_72383d98f44f666c$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8a04f86771d4d29eeccaedd8';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8a0b52974feae87ab4720b0d' and md5(to_jsonb(t)::text)='b7a237c7916ae864c1b5ae4a83e19982')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8a0b52974feae87ab4720b0d';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_18e6126021f5b235$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a una criatura con esta arma mágica y saques un 20 en la tirada de ataque, el objetivo sufrirá 3d6 de daño necrótico adicional si no es un autómata o un muerto viviente. Además, obtendrás una cantidad de puntos de golpe temporales igual al daño adicional infligido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_18e6126021f5b235$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8a0b52974feae87ab4720b0d';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8a613560179ce75309d54f99' and md5(to_jsonb(t)::text)='d385ce2fae953b211be29c5005ed4054')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8a613560179ce75309d54f99';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_6c180faeb5f5026f$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este colgante, te estabilizarás si estás agonizando al principio de tu turno. Además, cuando tires un Dado de Golpe para recuperar puntos de golpe, se duplicará la cantidad de puntos de golpe que recuperas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6c180faeb5f5026f$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8a613560179ce75309d54f99';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8a8fbb6b819be5eeb799cd18' and md5(to_jsonb(t)::text)='f8f58012ad8f5b5ef65e30a7ecf0b756')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8a8fbb6b819be5eeb799cd18';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_e722eefe44c85638$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes 10 puntos de golpe temporales que duran 1 hora a partir del momento en que bebes esta poción. Durante ese periodo, te encontrarás bajo el efecto del conjuro bendición (no requiere concentración). Esta poción azul borbotea y echa humo como si estuviera hirviendo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e722eefe44c85638$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8a8fbb6b819be5eeb799cd18';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8aa13b5042ba0f4052b7b278' and md5(to_jsonb(t)::text)='bedf7aad79692b602489b596dd48dd93')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8aa13b5042ba0f4052b7b278';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_40ec8342a824c4ae$"Objeto · Precio base · Peso\nPalanqueta · 2 po · 5 lb\n\nPalanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_40ec8342a824c4ae$::jsonb,true),'{features}',$text_6f1d9ea42031bbb9$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Palanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_6f1d9ea42031bbb9$::jsonb,true),'{rules,definition,description}',$text_e001331f02e6f861$[{"id":"official-table","rows":[["Palanqueta","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Palanqueta. Una palanqueta te da ventaja en aquellas pruebas de Fuerza en las que resulte útil hacer palanca.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_e001331f02e6f861$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:8aa13b5042ba0f4052b7b278';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8af13bb03749f70e9339f0cb' and md5(to_jsonb(t)::text)='9d4ae3d7bd50777dd9abd86e8765ca87')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8af13bb03749f70e9339f0cb';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5acce8575efbd176$"Objeto · Precio base · Peso\nSuministros de alquimista · 50 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5acce8575efbd176$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_d771e173c4434726$[{"id":"official-table","rows":[["Suministros de alquimista","50 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_d771e173c4434726$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:8af13bb03749f70e9339f0cb';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8b3fcc59e77077e00e089e90' and md5(to_jsonb(t)::text)='b7f96b72068702e58aeb9b7732596dc0')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8b3fcc59e77077e00e089e90';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_cee6b0c3dbb382f1$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta vara, podrás utilizar una acción para activarla. Os transportará instantánea- mente a ti y hasta otras 199 criaturas voluntarias que puedas ver a un paraíso situado en un espacio extraplanar. Puedes elegir la forma que adopta este paraíso. Podría ser un plácido jardín, un claro agradable, una taberna alegre, un palacio enorme, una isla tropical, una fantástica feria o cualquier cosa que puedas imaginar. Independientemente de su naturaleza, el paraíso contiene agua y comida suficientes para sustentar a sus visitantes. Cualquier otra cosa con la que se pueda interactuar en este espacio extraplanar solo podrá existir dentro de él. Por ejemplo, una flor recogida de un jardín del paraíso desaparece si se saca fuera del espacio extraplanar.\n\nPor cada hora que un visitante pase en el paraíso, recuperará tantos puntos de golpe como si hubiera gastado 1 Dado de Golpe. Además, las criaturas no envejecen mientras se encuentran en el paraíso, aunque el tiempo transcurre con normalidad. Los visitantes pueden permanecer en el paraíso hasta 200 días divididos por el número de criaturas que haya en él (redondeando hacia abajo).\n\nCuando el tiempo se agote o utilices una acción para finalizar el efecto, todos los visitantes reaparecerán en el lugar que ocupaban cuando activaste la vara o en el espacio sin ocupar más cercano a ese lugar. La vara no podrá usarse de nuevo hasta que hayan transcurrido 10 días.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cee6b0c3dbb382f1$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8b3fcc59e77077e00e089e90';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8b457fb486eaa62761e1af40' and md5(to_jsonb(t)::text)='d1de2bbcb0054327b2a2d3d4eefb275e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8b457fb486eaa62761e1af40';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_00fc3478083c3b24$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves prendido este broche, tendrás resistencia al daño de fuerza e inmunidad al daño infligido por el conjuro proyectil mágico.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_00fc3478083c3b24$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8b457fb486eaa62761e1af40';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8c43510ebccc077670038abb' and md5(to_jsonb(t)::text)='3d91b0ca816d19090d0812804c91f83e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8c43510ebccc077670038abb';end if;update public.official_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_cd4ebcae1032608c$"Objeto · Precio base · Peso\nMartillo · 1 po · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_cd4ebcae1032608c$::jsonb,true),'{rules,definition,description}',$text_11072c2cd0901b4c$[{"id":"official-table","rows":[["Martillo","1 po","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_11072c2cd0901b4c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true) where kind='equipment' and content_key='official:equipment:es:8c43510ebccc077670038abb';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8d85de3910c02958da0b2003' and md5(to_jsonb(t)::text)='7f5c205840ce9c61279edbb6e139316d')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8d85de3910c02958da0b2003';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_56cc57121c607185$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +2 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa espada tiene 1d8 + 1 cargas. Si causas un crítico contra una criatura que tenga menos de 100 puntos de golpe, deberá superar una tirada de salvación de Constitución con CD 15 o morirá al instante, ya que el arma arrancará la fuerza vital de su cuerpo (los autómatas o los muertos vivientes son inmunes). La espada pierde 1 carga si la criatura muere. El arma pierde esta propiedad si no le quedan cargas.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_56cc57121c607185$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8d85de3910c02958da0b2003';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8dd6403aac77cfcf26306fda' and md5(to_jsonb(t)::text)='c78cb71013ea12fae854a58a5a8ab47e')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8dd6403aac77cfcf26306fda';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_78a5ae1bb2b2a52b$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +2 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +2 a la CA. Además, si cualquier efecto te desplaza por el suelo contra tu voluntad, puedes usar tu reacción para reducir hasta 3 m la distancia en que te mueves.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78a5ae1bb2b2a52b$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8dd6403aac77cfcf26306fda';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8e74acfe2a0c28dcf4c90bd9' and md5(to_jsonb(t)::text)='c387e4595b7be9fcfcc2f5d491f96381')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8e74acfe2a0c28dcf4c90bd9';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_4679f8b93c97527e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nCono de terror. Mientras empuñes la varita, podrás usar una acción y gastar 2 cargas para que la punta de la varita emita un cono de 18 m de luz ámbar. Todas las criaturas situadas en el cono deberán superar una tirada de salvación de Sabiduría con CD 15 o quedarán asustadas de ti durante 1 minuto. Una criatura asustada de esta manera deberá dedicar sus turnos a tratar de alejarse de ti todo lo que pueda y no podrá acercarse voluntariamente a ningún espacio que se encuentre a 9 m o menos de ti. Tampoco podrá llevar a cabo reacciones. Tan solo podrá realizar la acción de correr o intentar escapar de un efecto que le impida moverse. Si no tiene adónde ir, la criatura podrá usar la acción de esquivar. Al final de cada uno de sus turnos, la criatura podrá repetir la tirada de salvación y, si tiene éxito, se librará del efecto.\n\nOrden. Mientras empuñes la varita, podrás usar una acción para gastar 1 carga y ordenar a otra criatura que huya o se postre, como con el conjuro orden imperiosa (CD de salvación de conjuros 15).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4679f8b93c97527e$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8e74acfe2a0c28dcf4c90bd9';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8e9870158921c82b6141bae1' and md5(to_jsonb(t)::text)='ca91ea94352e6e110e6cdecbbbc98dfa')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8e9870158921c82b6141bae1';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_56cdea340ebd3b00$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, podrás utilizar una acción para lanzar a voluntad el conjuro levitar sobre ti.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_56cdea340ebd3b00$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8e9870158921c82b6141bae1';
if not exists(select 1 from public.official_content_entries t where kind='equipment' and content_key='official:equipment:es:8ec089ba90c7b3afc8bb2f17' and md5(to_jsonb(t)::text)='3363fa9e519670c112bd40a5098af2b4')then raise exception 'ITEM_TEXT_CONFLICT:shared:official:equipment:es:8ec089ba90c7b3afc8bb2f17';end if;update public.official_content_entries set payload=jsonb_set(payload,'{features}',$text_0f41f81ff846d525$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar el conjuro bola de fuego (CD de salvación 15) desde ella. Si empleas 1 carga, podrás lanzar la versión de nivel 3 del conjuro. Puedes aumentar el nivel del espacio de conjuro en 1 por cada carga adicional que emplees.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_0f41f81ff846d525$::jsonb,true) where kind='equipment' and content_key='official:equipment:es:8ec089ba90c7b3afc8bb2f17';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 14 as batch,47 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;